import type { ReactNode } from "react";
import { protocolIconSrc } from "@/lib/shared/protocols";

/**
 * Monochrome protocol glyphs — used in compact chrome (bookmarks, wallet
 * history, the header context mark) where a colour logo would shout.
 *
 * Unlike the colour PNG logos (`/icons/protocols/<id>.png`, drawn with a raw
 * `<img>`), these are inline SVG paths with no baked-in colour: they paint with
 * `fill="currentColor"`, so they inherit the surrounding text colour and invert
 * cleanly between light and dark themes. Keyed by the protocol `id` from
 * `lib/shared/protocols.ts`. The directory surfaces (home row, nav
 * dropdown/sheet, /coverage) all render glyphs, keeping the colour PNGs as
 * fallback only — a newly onboarded protocol shows its PNG until its glyph
 * is added here, so adding one is part of bringing an explorer up.
 *
 * Add a protocol by dropping a `{ viewBox, paths }` entry below — paste the
 * source SVG's `viewBox` and each `<path>`'s `d` (+ `fillRule: "evenodd"` when
 * the source path had it). Strip any hard-coded `fill`/`stroke`/`style` — the
 * component supplies the colour.
 *
 * Surfaces that render a glyph should prefer it and fall back to the PNG when
 * one isn't defined yet:
 *
 *   hasProtocolGlyph(id)
 *     ? <ProtocolGlyph id={id} className="h-5 w-5 shrink-0" />
 *     : <img src={protocolIconSrc(id)} alt="" className="h-5 w-5 shrink-0 rounded" />
 */

export type Glyph = {
  viewBox: string;
  paths?: { d: string; fillRule?: "evenodd" | "nonzero"; opacity?: number }[];
  /** Some marks (e.g. pixel-font wordmarks) are authored as rects, not paths. */
  rects?: { x?: number; y?: number; width: number; height: number }[];
  /** Group transform (e.g. the scale/translate matrices the source wrapped its
   *  paths in) applied to a `<g>` around the geometry, so path coordinates need
   *  no rebasing into the viewBox. */
  transform?: string;
  /** Optical-padding trim: fraction of the box to shrink the mark by, scaled
   *  about the viewBox centre, composed *outside* `transform` (so it always
   *  reads in viewBox space regardless of how the mark itself is authored).
   *  Measured via `getBBox()`, most marks land at ~74–87% fill (max of the
   *  bbox's width/height axis vs the viewBox's) with no help — that band is
   *  the target. Set `inset` only on the outliers that fill (or nearly fill)
   *  their viewBox edge-to-edge, so every glyph reads at a consistent optical
   *  size at any caller box size; leave marks already in the band alone. */
  inset?: number;
};

